// Loads the synthetic diary pages (`fixtures/diary`, regenerated by `generate.mjs`) for the tests.
import { readdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import type { RawDiaryEntry } from './structure.ts';
import type { OcrLine } from '../ocr/line-boxes.ts';

const dir = join(dirname(fileURLToPath(import.meta.url)), '..', '..', 'fixtures', 'diary');

/** The element, or a failing test: indexing is `T | undefined` under noUncheckedIndexedAccess. */
export function must<T>(value: T | undefined): T {
  if (value === undefined) throw new Error('expected a value');
  return value;
}

export interface TruthEntry {
  line: number;
  kind: RawDiaryEntry['kind'];
  caseRef?: string;
  nextDate: string | null;
  phrase?: string;
}

export interface DiaryFixture {
  name: string;
  lang: 'en' | 'ta' | 'kn';
  text: string;
  confidence: number;
  lines: OcrLine[];
  truth: TruthEntry[];
}

export function loadDiaryFixtures(): DiaryFixture[] {
  return readdirSync(dir)
    .filter((file) => file.endsWith('.ocr.json'))
    .sort()
    .map((file) => {
      const json = JSON.parse(readFileSync(join(dir, file), 'utf8')) as {
        pages: { text: string; confidence: number; lines: OcrLine[] }[];
        truth: { entries: TruthEntry[] };
      };
      const page = must(json.pages[0]);
      const name = file.replace('.ocr.json', '');
      return {
        name,
        lang: name.slice(0, 2) as DiaryFixture['lang'],
        text: page.text,
        confidence: page.confidence,
        lines: page.lines,
        truth: json.truth.entries,
      };
    });
}

/** What a faithful model would return for the fixture: its truth, cited by line number. */
export function modelAnswer(fixture: DiaryFixture): RawDiaryEntry[] {
  return fixture.truth.map((t) => ({
    text: must(fixture.lines[t.line - 1]).text,
    kind: t.kind,
    line: t.line,
    ...(t.caseRef === undefined ? {} : { caseRef: t.caseRef }),
    ...(t.nextDate === null || t.phrase === undefined
      ? {}
      : { nextDate: { date: t.nextDate, phrase: t.phrase, line: t.line } }),
  }));
}
